/**
 * Skill Flow tab, LOCAL mode, desktop + mobile: real frontend (Vite) + real API (scripts/e2e_mock_server.py: real
 * routes, storage and Docker sandbox; only the LLM is MOCKED). The Skill used is the human-written REFERENCE Skill
 * react-accessibility-analyzer, seeded by the API with its real stored report: nothing here is generated by a model.
 * One test intercepts the file route to simulate a storage failure (MOCKED failure, marked below).
 */
import { expect, test, type Page } from "@playwright/test";

const API = "http://127.0.0.1:8000";
let id = "";

test.beforeAll(async ({ request }) => {
  // idempotent; this spec must not depend on another spec having seeded first
  const seed = await request.post(`${API}/studio/reference/seed`, { timeout: 120_000 });
  expect(seed.ok(), `seeding answered ${seed.status()}`).toBeTruthy();
  const rows = (await seed.json()) as { slug: string; version_id: string }[];
  id = rows.find((r) => r.slug === "react-accessibility-analyzer")?.version_id ?? "";
  expect(id, "reference Skill seeded by the API").not.toBe("");
});

function watch(page: Page) {
  const problems: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") problems.push(`console: ${m.text()}`); });
  page.on("pageerror", (e) => problems.push(`pageerror: ${e.message}`));
  page.on("response", (r) => { if (r.status() >= 400) problems.push(`HTTP ${r.status()} ${r.url()}`); });
  page.on("requestfailed", (r) => problems.push(`failed ${r.url()}`));
  return problems;
}
const node = (page: Page, nid: string) => page.locator(`button[data-node="${nid}"]`);

test("the diagram shows the real structure, with measured connectors, on desktop and mobile", async ({ page }, info) => {
  const problems = watch(page);
  await page.goto(`/#/code/${id}/flow`);
  const flow = page.getByTestId("skill-flow");
  await expect(flow).toBeVisible();
  await expect(page.getByRole("tab", { name: "Flow" })).toHaveAttribute("aria-selected", "true");
  await expect(page.getByTestId("sf-diagram")).toHaveAttribute("data-layout", info.project.name === "mobile" ? "rail" : "lanes");
  for (const nid of ["input", "validation", "execution", "output", "evaluation", "fn:_has", "fn:_check", "fn:run", "tests", "checks", "docs"])
    await expect(node(page, nid), nid).toBeVisible();
  await expect(node(page, "execution")).toHaveAttribute("data-state", "passed");
  await expect(node(page, "fn:run")).toHaveAttribute("data-source", "scanned");
  await expect(page.getByTestId("sf-approx")).toContainText("approximate");
  // connectors: one SVG path per evidence-backed edge, with real coordinates
  const paths = page.locator("[data-testid=sf-edges] path[data-edge]");
  await expect(paths.first()).toBeAttached();
  const ds = await paths.evaluateAll((els) => els.map((e) => e.getAttribute("d") ?? ""));
  expect(ds.length).toBeGreaterThanOrEqual(9);
  expect(ds.every((d) => d.length > 5 && !d.includes("NaN"))).toBe(true);
  for (const e of ["input>validation", "validation>execution", "execution>output", "output>evaluation", "fn:run>fn:_check", "fn:_check>fn:_has"])
    await expect(page.locator(`[data-testid=sf-edges] path[data-edge="${e}"]`), e).toHaveCount(1);
  expect(await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1);
  expect(problems).toEqual([]);
});

test("details → 'Open in Code Workspace' opens the file at the function's lines", async ({ page }) => {
  const problems = watch(page);
  await page.goto(`/#/code/${id}/flow`);
  await node(page, "fn:_check").click();
  const detail = page.getByTestId("sf-detail");
  await expect(detail).toHaveAttribute("data-node", "fn:_check");
  await expect(detail.getByText("A function defined in the entrypoint")).toBeVisible();
  await expect(detail.locator("[data-focus]")).toHaveCount(15); // def _check … (lines 12–26, as Python's ast reports)
  await detail.getByRole("link", { name: "Open in Code Workspace" }).click();
  await expect(page).toHaveURL(new RegExp(`#/code/${id}/files/scripts%2Fmain\\.py/12-26$`));
  await expect(page.getByRole("tab", { name: /^Files/ })).toHaveAttribute("aria-selected", "true");
  const preview = page.getByLabel("file preview");
  await expect(preview.locator("[data-focus]")).toHaveCount(15);
  await expect(preview.locator('[data-line="12"]')).toBeInViewport();
  await expect(preview.locator('[data-line="12"]')).toContainText("def _check(tag, attrs):");
  expect(problems).toEqual([]);
});

test("keyboard: arrows move between steps, Enter selects, focus is visible", async ({ page }) => {
  await page.goto(`/#/code/${id}/flow`);
  await node(page, "input").focus();
  await page.keyboard.press("ArrowDown");
  await expect(node(page, "validation")).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(node(page, "validation")).toHaveAttribute("aria-pressed", "true");
  await expect(page.getByTestId("sf-detail")).toHaveAttribute("data-node", "validation");
  const ring = await node(page, "validation").evaluate((el) => getComputedStyle(el).boxShadow);
  expect(ring).not.toBe("none"); // focus-visible ring
  await page.keyboard.press("End");
  await expect(page.locator("button[data-node]").last()).toBeFocused();
});

test("the validation step says it is done by the platform and not necessarily in the ZIP", async ({ page }) => {
  await page.goto(`/#/code/${id}/flow`);
  await node(page, "validation").click();
  const detail = page.getByTestId("sf-detail");
  await expect(detail).toContainText("not necessarily included in the exported ZIP");
  await expect(detail.locator('[data-fact="platform_input_check"]')).toContainText("when the Skill runs through the API");
  await expect(detail.locator('[data-fact="not_in_zip"]')).toContainText("the ZIP runs the scripts directly");
});

test("files are fetched once per version: switching Files ↔ Flow does not request them again", async ({ page }) => {
  const seen: string[] = [];
  page.on("request", (r) => { if (r.url().includes(`/versions/${id}/files/`)) seen.push(decodeURIComponent(r.url().split("/files/")[1])); });
  await page.goto(`/#/code/${id}/flow`);
  await expect(page.getByTestId("skill-flow")).toBeVisible();
  await page.getByRole("tab", { name: /^Files/ }).click();
  await page.getByRole("tab", { name: "Flow" }).click();
  await expect(page.getByTestId("skill-flow")).toBeVisible();
  const counts = seen.reduce<Record<string, number>>((a, p) => ({ ...a, [p]: (a[p] ?? 0) + 1 }), {});
  expect(Object.entries(counts).filter(([, n]) => n > 1)).toEqual([]);
});

test("storage failure (MOCKED via route interception): error state, then 'Try again' recovers", async ({ page }) => {
  await page.route(`**/versions/${id}/files/**`, (r) => r.fulfill({ status: 503, contentType: "application/json", body: '{"detail":"storage down"}' }));
  await page.goto(`/#/code/${id}/flow`);
  // the app's retry policy (api.ts shouldRetry) retries a 5xx 3 times with backoff (~7 s) before giving up
  await expect(page.getByTestId("sf-error")).toContainText("The Skill's files could not be loaded.", { timeout: 20_000 });
  await page.unroute(`**/versions/${id}/files/**`);
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(page.getByTestId("skill-flow")).toBeVisible();
  await expect(node(page, "execution")).toHaveAttribute("data-state", "passed");
});
